<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\Product; use App\Services\AuditService; use Illuminate\Http\Request; use Illuminate\Support\Str;
class ProductController extends Controller { public function index(){return view('admin.resource',['title'=>__('ui.products'),'columns'=>['name','slug','status'],'rows'=>Product::latest()->paginate(20),'createRoute'=>route('products.create')]);} public function create(){return view('admin.form',['title'=>__('ui.new_product'),'action'=>route('products.store'),'fields'=>['name'=>'text','slug'=>'text','description'=>'textarea','status'=>'select:active,inactive']]);} public function store(Request $r,AuditService $audit){$data=$r->validate(['name'=>'required|max:255','slug'=>'nullable|alpha_dash|unique:products,slug','description'=>'nullable','status'=>'required|in:active,inactive']);$data['slug']=$data['slug']?:Str::slug($data['name']);$model=Product::create($data);$audit->record('product.created',$model,null,$model->toArray());return redirect()->route('products.index')->with('success',__('ui.saved'));} }
